"use strict";(self.webpackChunkultimatelearning=self.webpackChunkultimatelearning||[]).push([[433],{433:e=>{e.exports=JSON.parse('{"topic":{"id":"arrays","title":"Arrays","overviewSimple":"Imagine you have a long egg carton. Each egg slot can store something like a number or word. That\u2019s exactly how an array works in Java \u2014 a fixed number of slots storing values of the same type.","overviewTechnical":["An array in Java is a fixed-size data structure that stores elements of the same data type in contiguous memory locations.","Arrays are objects in Java, meaning they are allocated on the heap and have a \'length\' property.","Java supports both single-dimensional and multi-dimensional arrays.","Array indices start from 0 and accessing an invalid index causes ArrayIndexOutOfBoundsException.","Arrays can store primitives (int, double, char) or references to objects."],"story":"A kid named Ria sorted her toy cars into a long tray with numbered slots. She always knew which car was in which slot. Java arrays work the same way \u2014 organized and easy to find!","realWorldAnalogy":"An array is like a row of labeled mailboxes. Each mailbox has a number (index) and can hold one specific type of item.","keyPoints":["Fixed size \u2014 cannot grow or shrink","Fast access using index","Stores values of the same type","Supports multi-dimensional arrays"],"exampleSimple":"int[] numbers = {1, 2, 3, 4, 5};\\nSystem.out.println(numbers[0]);  // prints 1","exampleTechnical":["int[] marks = new int[5];\\nmarks[0] = 90;\\nmarks[1] = 85;\\nmarks[2] = 88;\\nSystem.out.println(\\"First mark: \\" + marks[0]);","int[][] matrix = {\\n  {1, 2, 3},\\n  {4, 5, 6}\\n};\\nSystem.out.println(matrix[1][2]);  // prints 6"],"extraNotes":["Arrays are the foundation for data structures like ArrayList, HashMap buckets, and queues.","Enhanced for-loops simplify looping through array values."],"bestPracticesSimple":["Always check array size before accessing","Use loops to work with all elements"],"bestPracticesAdvanced":["Prefer ArrayList when working with dynamic collections","Avoid hard-coded indices \u2014 use loops or constants","Validate user input to prevent ArrayIndexOutOfBoundsException"]}}')}}]);